import test from 'node:test';
import assert from 'node:assert/strict';
import { statement } from '../src/statements.js';
import { createInvoice } from '../src/invoices.js';
import { issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('statement shows customer invoices', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const result = statement('C-001', [issued1.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].issueDate, '2026-10-07');
});

test('statement filters by customer', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const invoice2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);
  const result = statement('C-001', [issued1.value, issued2.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, 'INV-2026-0001');
});

test('statement filters by status', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const draft = invoice1.value;
  const issued1 = issueInvoice(invoice1.value, []);
  const result = statement('C-001', [draft, issued1.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
});

test('statement filters by date', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-11-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);
  const result = statement('C-001', [issued1.value, issued2.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].issueDate, '2026-10-07');
});

test('statement includes date boundary', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-31',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const result = statement('C-001', [issued.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
});

test('statement excludes future invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-11-01',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const result = statement('C-001', [issued.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
});

test('statement includes partially_paid invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const payment = recordPayment(issued.value, { amount: 500000, date: '2026-10-15' });
  const result = statement('C-001', [payment.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
});

test('statement includes due amounts', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const result = statement('C-001', [issued.value], '2026-10-31');
  assert.equal(result.ok, true);
  // Total: 1034550
  assert.equal(result.value.invoices[0].due, 1034550);
  assert.equal(result.value.totalDue, 1034550);
});

test('statement calculates totalDue', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DEV-HOUR', qty: 50, discountPercent: 0 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);
  const result = statement('C-001', [issued1.value, issued2.value], '2026-10-31');
  assert.equal(result.ok, true);
  // Invoice1: 1034550, Invoice2: 1197562 (50*9500=475000, VAT 21%=99750, total=574750)
  assert.equal(result.value.totalDue, 1034550 + 574750);
});

test('statement reduces due by partial payment', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100, discountPercent: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const payment = recordPayment(issued.value, { amount: 500000, date: '2026-10-15' });
  const result = statement('C-001', [payment.value], '2026-10-31');
  assert.equal(result.ok, true);
  // Total: 1034550, Paid: 500000, Due: 534550
  assert.equal(result.value.invoices[0].due, 534550);
  assert.equal(result.value.totalDue, 534550);
});

test('statement sorts by issueDate', () => {
  const invoice1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-20',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued1 = issueInvoice(invoice1.value, []);
  const invoice2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued2 = issueInvoice(invoice2.value, ['INV-2026-0001']);
  const result = statement('C-001', [issued1.value, issued2.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices[0].issueDate, '2026-10-07');
  assert.equal(result.value.invoices[1].issueDate, '2026-10-20');
});

test('statement returns empty list for no matching invoices', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const result = statement('C-002', [invoice.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.totalDue, 0);
});

test('statement rejects unknown customer', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const result = statement('C-999', [invoice.value], '2026-10-31');
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('statement rejects invalid asOf date', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const result = statement('C-001', [invoice.value], '2026-10-7');
  assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' });
});

test('statement normalizes customer ID', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });
  const issued = issueInvoice(invoice.value, []);
  const result = statement('c-001 ', [issued.value], '2026-10-31');
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.invoices.length, 1);
});

test('statement includes invoice details', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
    terms: 'NET14',
  });
  const issued = issueInvoice(invoice.value, []);
  const result = statement('C-001', [issued.value], '2026-10-31');
  assert.equal(result.ok, true);
  const inv = result.value.invoices[0];
  assert.equal(inv.number, 'INV-2026-0001');
  assert.equal(inv.issueDate, '2026-10-07');
  assert.equal(inv.dueDate, '2026-10-21');
});

